import { apiGet, buildPath } from "../host/server/typed-client.js";
import { requestRaw } from "../host/server/python-client.js";
async function fetchPendingActionRequests() {
  const { data } = await apiGet("/action-requests/pending");
  const requests = data?.requests;
  return Array.isArray(requests) ? requests : [];
}
async function completeActionRequestAsSelf(requestId, organizationId, answer) {
  const response = await requestRaw(
    buildPath("/action-requests/{request_id}/complete", { request_id: requestId }),
    {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(answer)
    },
    {
      organizationId,
      allowHttpError: true,
      expectedErrorStatuses: [400, 409]
    }
  );
  const body = await response.json().catch(() => null);
  return { status: response.status, body };
}
export {
  completeActionRequestAsSelf,
  fetchPendingActionRequests
};
